import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    static final ReentrantLock LOCK = new ReentrantLock(true);
    static final Condition NOT_EMPTY = LOCK.newCondition();
    static final Deque<Integer> QUEUE = new ArrayDeque<>();
    static volatile boolean producedAll = false;

    static void outer() {
        LOCK.lock();
        try {
            System.out.println("holdCount outside inner = " + LOCK.getHoldCount());
            inner();
        } finally { LOCK.unlock(); }
    }

    static void inner() {
        LOCK.lock();
        try { System.out.println("holdCount inside  inner = " + LOCK.getHoldCount()); }
        finally { LOCK.unlock(); }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("fair lock enabled       : " + LOCK.isFair());
        outer();
        System.out.println("holdCount after release = " + LOCK.getHoldCount());

        Thread consumer = new Thread(() -> {
            LOCK.lock();
            try {
                StringBuilder sb = new StringBuilder();
                while (true) {
                    while (QUEUE.isEmpty()) {
                        if (producedAll) { System.out.println("consumed sequence       : " + sb.toString().trim()); return; }
                        NOT_EMPTY.await();
                    }
                    sb.append(QUEUE.poll()).append(' ');
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally { LOCK.unlock(); }
        }, "consumer");
        consumer.start();

        for (int i = 1; i <= 5; i++) {
            LOCK.lock();
            try {
                QUEUE.add(i);
                if (i == 5) producedAll = true;
                NOT_EMPTY.signalAll();
            } finally { LOCK.unlock(); }
        }
        consumer.join(3000L);
        System.out.println("consumer finished       : " + !consumer.isAlive());
    }
}
